curl -s -X POST "https://slack.com/api/conversations.list?token=<TOKEN>&types=public_channel,private_channel&limit=1000" | python3 -c "
import json,sys
data=json.load(sys.stdin)
if not data.get('ok'):
    print('ERROR:', data.get('error'))
    sys.exit(1)
for c in data['channels']:
    if 'payments' in c.get('name','').lower():
        print(c['id'], '|', c['name'], '| is_private:', c.get('is_private', False), '| archived:', c.get('is_archived', False))
"
